mapper.select:
SELECT pr.id, pr.user_id, u.nickname, pr.change_type, pr.change_point, pr.balance_after, pr.trigger_scene, pr.remark, pr.create_time FROM points_record pr LEFT JOIN user_info u ON pr.user_id = u.id AND u.del_flag = '0'
AND u.nickname LIKE CONCAT('%', #{nickname}, '%')
AND pr.change_type = #{changeType}
AND pr.create_time >= #{beginTime}
AND pr.create_time <= #{endTime}
ORDER BY pr.create_time DESC
